def main():
    TEXT[64][IDS.index(20)]='前辈，只能用物理技能，\n要注意！'
    TEXT[65][IDS.index(21)]='队长，无法闪避或逃跑，\n要小心！'
    path=ROOT/'translation/batches/416_rise_binds_debuffs.generated.json';assert not path.exists()
    catalog={r['key']:r for r in read(ROOT/'translation/catalog.working.json')};sources=defaultdict(list);seen={}
    for m,values in TEXT.items():
        assert len(values)==20
        s=f'export_base/battle/support/bsv105.bvp_({m:03}).BMD.json';doc=read(ROOT/s)
        for i,body in zip(IDS,values):
            r=catalog[f'{s}:{i}:0'];assert not r.get('translation');body+='\n'
            a=TOKEN.sub('',r['original']).splitlines();b=body.splitlines()
            assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(m,i,a,b)
            if r['original'] in seen:assert seen[r['original']]==body
            seen[r['original']]=body
            sources[s].append([i,0,doc['texts'][i]['id'],body])
    write(path,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['本体理世061/062/064—068有效140页，保留占位，063已由414精确复用。','064只能物理攻击；065无法闪避及逃跑；三个能力下降方向保持一致。善单人/善玲双人按各页原文保留，不机械替换。未运行验证。']))
    print('Rise binds/debuffs:',sum(map(len,sources.values())))

if __name__=='__main__':main()
